import{_ as e,H as t,f as i,i as o}from"./chunks/framework.Cvt1eIE0.js";const g=JSON.parse('{"title":"14-에이전트 모드 (ACP)","description":"","frontmatter":{},"headers":[],"relativePath":"15-agent-mode.md","filePath":"15-agent-mode.md","lastUpdated":1778828590000}'),s={name:"15-agent-mode.md"};function l(d,a,r,h,n,p){return t(),i("div",null,[...a[0]||(a[0]=[o('<h1 id="_14-에이전트-모드-acp" tabindex="-1">14-에이전트 모드 (ACP) <a class="header-anchor" href="#_14-에이전트-모드-acp" aria-label="Permalink to &quot;14-에이전트 모드 (ACP)&quot;">​</a></h1><p>Grok Build는 기본적으로 터미널에서 직접 실행하는 TUI 방식으로 사용합니다.<br> 하지만 IDE(통합 개발 환경)나 다른 프로그램 안에서 Grok을 사용하고 싶을 때가 있습니다.</p><p>이럴 때 사용하는 것이 바로 <strong>Agent Mode</strong>입니다.</p><hr><h2 id="agent-mode란-무엇인가" tabindex="-1">Agent Mode란 무엇인가? <a class="header-anchor" href="#agent-mode란-무엇인가" aria-label="Permalink to &quot;Agent Mode란 무엇인가?&quot;">​</a></h2><p><strong>Agent Mode</strong>는 Grok Build를 <strong>ACP(Agent Client Protocol)</strong> 서버로 실행해서, IDE나 에디터, 커스텀 도구와 연동할 수 있게 해주는 모드입니다.</p><h3 id="acp-agent-client-protocol-란" tabindex="-1">ACP(Agent Client Protocol)란? <a class="header-anchor" href="#acp-agent-client-protocol-란" aria-label="Permalink to &quot;ACP(Agent Client Protocol)란?&quot;">​</a></h3><p>ACP는 AI 에이전트와 클라이언트(IDE, 에디터, 앱) 간의 <strong>표준 통신 규약</strong>입니다.<br> JSON-RPC라는 구조화된 메시지 형식을 사용해서 다음과 같은 일을 할 수 있습니다:</p><ul><li>대화 세션 생성, 불러오기, 이어가기</li><li>사용자 메시지 전송 및 응답 받기 (스트리밍 포함)</li><li>Grok이 어떤 도구를 사용 중인지 실시간으로 보기</li><li>Grok의 사고 과정(Thinking) 실시간 관찰</li><li>도구 실행 권한을 실시간으로 승인/거부</li></ul><p>쉽게 말해, <strong>Grok을 IDE 안에 &quot;살아있는 AI 페어 프로그래머&quot;로 넣는 방식</strong>입니다.</p><hr><h2 id="stdio-transport-가장-흔한-방식" tabindex="-1">stdio Transport (가장 흔한 방식) <a class="header-anchor" href="#stdio-transport-가장-흔한-방식" aria-label="Permalink to &quot;stdio Transport (가장 흔한 방식)&quot;">​</a></h2><p>Agent Mode의 가장 기본적인 실행 방식은 <code>stdio</code>입니다.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">grok</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agent</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stdio</span></span></code></pre></div><p>이 명령어를 실행하면 Grok이 JSON-RPC 메시지를 stdin/stdout으로 주고받는 ACP 서버가 됩니다.</p><h3 id="주로-사용되는-곳" tabindex="-1">주로 사용되는 곳 <a class="header-anchor" href="#주로-사용되는-곳" aria-label="Permalink to &quot;주로 사용되는 곳&quot;">​</a></h3><ul><li><strong>Zed</strong> 에디터</li><li><strong>Neovim</strong> (ACP 플러그인)</li><li><strong>Emacs</strong> (ACP 지원)</li><li>기타 ACP를 지원하는 IDE나 커스텀 도구</li><li>ACP 클라이언트 라이브러리를 사용하는 프로그램</li></ul><h3 id="옵션" tabindex="-1">옵션 <a class="header-anchor" href="#옵션" aria-label="Permalink to &quot;옵션&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">grok</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agent</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stdio</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --model</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> grok-build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --yolo</span></span></code></pre></div><ul><li><code>-m, --model</code>: 사용할 모델 지정</li><li><code>--yolo</code>: 모든 도구 실행을 자동 승인 (주의 필요)</li><li><code>--reauth</code>: 강제로 재인증 진행</li></ul><hr><h2 id="server-mode-http" tabindex="-1">Server Mode (HTTP) <a class="header-anchor" href="#server-mode-http" aria-label="Permalink to &quot;Server Mode (HTTP)&quot;">​</a></h2><p>stdio 방식 외에도, HTTP 서버 형태로 Agent Mode를 실행할 수 있습니다.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">grok</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agent</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> serve</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --bind</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 127.0.0.1:2419</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --secret</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-secret-token</span></span></code></pre></div><h3 id="옵션-설명" tabindex="-1">옵션 설명 <a class="header-anchor" href="#옵션-설명" aria-label="Permalink to &quot;옵션 설명&quot;">​</a></h3><ul><li><code>--bind</code>: 어떤 주소와 포트로 열지 지정</li><li><code>--secret</code>: 접속 시 필요한 비밀 토큰 (보안용)</li></ul><p>이 방식은 네트워크를 통해 여러 클라이언트가 Grok에 접근할 수 있게 해줍니다.<br> (예: 팀 내부에서 공유하는 AI 에이전트 서버)</p><hr><h2 id="agent-mode-vs-headless-mode" tabindex="-1">Agent Mode vs Headless Mode <a class="header-anchor" href="#agent-mode-vs-headless-mode" aria-label="Permalink to &quot;Agent Mode vs Headless Mode&quot;">​</a></h2><p>많은 사람들이 혼동하는 부분이 Agent Mode와 Headless Mode의 차이입니다.</p><table tabindex="0"><thead><tr><th>구분</th><th>Headless Mode</th><th>Agent Mode (ACP)</th></tr></thead><tbody><tr><td>실행 방식</td><td>한 번 실행 → 결과 받고 종료</td><td>지속적으로 실행 (서버 형태)</td></tr><tr><td>통신 방식</td><td>표준 입출력 (텍스트/JSON)</td><td>JSON-RPC (구조화된 메시지)</td></tr><tr><td>세션 관리</td><td>제한적</td><td>세션 생성/로드/이어하기 완벽 지원</td></tr><tr><td>도구 확인</td><td>결과에 포함</td><td>실시간으로 어떤 도구를 쓰는지 관찰 가능</td></tr><tr><td>권한 처리</td><td>YOLO 또는 사전 승인</td><td>실시간으로 권한 요청/승인 가능</td></tr><tr><td>주요 용도</td><td>스크립트, CI/CD, 자동화</td><td>IDE 연동, 실시간 협업</td></tr></tbody></table><p><strong>한 줄 요약</strong>:</p><ul><li><strong>Headless Mode</strong>: &quot;Grok에게 일 시키고 결과 받기&quot;</li><li><strong>Agent Mode</strong>: &quot;Grok을 항상 켜두고 실시간으로 함께 작업하기&quot;</li></ul><hr><h2 id="agent-mode에서-실제로-어떤-일이-일어나나" tabindex="-1">Agent Mode에서 실제로 어떤 일이 일어나나? <a class="header-anchor" href="#agent-mode에서-실제로-어떤-일이-일어나나" aria-label="Permalink to &quot;Agent Mode에서 실제로 어떤 일이 일어나나?&quot;">​</a></h2><p>Agent Mode(stdio)로 실행하면, Grok은 JSON-RPC 메시지를 주고받으며 다음과 같은 흐름으로 동작합니다.</p><h3 id="_1-세션-생성-로드" tabindex="-1">1. 세션 생성 / 로드 <a class="header-anchor" href="#_1-세션-생성-로드" aria-label="Permalink to &quot;1. 세션 생성 / 로드&quot;">​</a></h3><p>IDE(또는 클라이언트)가 Grok에 연결되면, 먼저 세션을 생성하거나 기존 세션을 로드합니다.</p><ul><li><code>session/new</code>: 새 세션 생성</li><li><code>session/load</code>: 기존 세션 불러오기</li></ul><h3 id="_2-프롬프트-전송" tabindex="-1">2. 프롬프트 전송 <a class="header-anchor" href="#_2-프롬프트-전송" aria-label="Permalink to &quot;2. 프롬프트 전송&quot;">​</a></h3><p>사용자가 메시지를 입력하면, IDE가 <code>prompt/send</code> 요청을 보냅니다.</p><p>Grok은 이 프롬프트를 받아서 처리하고, 결과를 스트리밍으로 돌려줍니다.</p><h3 id="_3-도구-호출-tool-call" tabindex="-1">3. 도구 호출 (Tool Call) <a class="header-anchor" href="#_3-도구-호출-tool-call" aria-label="Permalink to &quot;3. 도구 호출 (Tool Call)&quot;">​</a></h3><p>Grok이 코드를 읽거나, 파일을 수정하거나, shell 명령을 실행해야 할 때:</p><ul><li><code>tool/call</code> 요청을 IDE 쪽으로 보냄</li><li>IDE는 사용자에게 권한을 물어보거나, 자동으로 승인</li><li>결과(<code>tool/result</code>)를 다시 Grok에게 전달</li></ul><h3 id="_4-사고-과정-thought-stream" tabindex="-1">4. 사고 과정 (Thought Stream) <a class="header-anchor" href="#_4-사고-과정-thought-stream" aria-label="Permalink to &quot;4. 사고 과정 (Thought Stream)&quot;">​</a></h3><p>Grok이 생각하는 과정(Thinking Block)을 실시간으로 IDE에 스트리밍할 수 있습니다.</p><ul><li>IDE는 이 사고 과정을 실시간으로 사용자에게 보여줄 수 있음</li><li>&quot;Grok이 지금 무슨 생각을 하고 있는지&quot; 투명하게 관찰 가능</li></ul><h3 id="_5-세션-종료" tabindex="-1">5. 세션 종료 <a class="header-anchor" href="#_5-세션-종료" aria-label="Permalink to &quot;5. 세션 종료&quot;">​</a></h3><p>연결이 끊기거나, 사용자가 명시적으로 종료하면 세션이 종료됩니다.</p><hr><h2 id="permission-handling-실시간-권한-관리" tabindex="-1">Permission Handling (실시간 권한 관리) <a class="header-anchor" href="#permission-handling-실시간-권한-관리" aria-label="Permalink to &quot;Permission Handling (실시간 권한 관리)&quot;">​</a></h2><p>Agent Mode의 가장 큰 장점 중 하나는 <strong>도구 실행 권한을 실시간으로 관리</strong>할 수 있다는 점입니다.</p><h3 id="동작-방식" tabindex="-1">동작 방식 <a class="header-anchor" href="#동작-방식" aria-label="Permalink to &quot;동작 방식&quot;">​</a></h3><ol><li>Grok이 <code>write_file</code>이나 <code>run_shell</code> 같은 도구를 사용하려고 함</li><li>ACP를 통해 IDE에 권한 요청 메시지 전송</li><li>IDE가 사용자에게 &quot;이 파일을 수정해도 될까요?&quot;라고 물음</li><li>사용자가 승인/거부</li><li>결과가 Grok에게 전달됨</li></ol><h3 id="yolo-모드" tabindex="-1">YOLO 모드 <a class="header-anchor" href="#yolo-모드" aria-label="Permalink to &quot;YOLO 모드&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">grok</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agent</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stdio</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --yolo</span></span></code></pre></div><p><code>--yolo</code> 옵션을 사용하면, 모든 도구 실행을 자동으로 승인합니다.</p><p><strong>주의</strong>: 편리하지만 보안상 위험할 수 있으니, 신뢰할 수 있는 환경에서만 사용하세요.</p><hr><h2 id="thought-streams-사고-과정-관찰" tabindex="-1">Thought Streams (사고 과정 관찰) <a class="header-anchor" href="#thought-streams-사고-과정-관찰" aria-label="Permalink to &quot;Thought Streams (사고 과정 관찰)&quot;">​</a></h2><p>Agent Mode에서는 Grok이 생각하는 과정을 실시간으로 관찰할 수 있습니다.</p><ul><li>&quot;지금 이 파일을 읽고 있음&quot;</li><li>&quot;이 변경을 위해 어떤 접근이 좋을지 고민 중&quot;</li><li>&quot;이전 대화에서 언급된 내용을 참고하고 있음&quot;</li></ul><p>이러한 Thought Stream은 IDE에서 &quot;Grok이 지금 무슨 생각을 하고 있는지&quot;를 사용자에게 보여주는 데 사용됩니다.</p><p>이는 단순한 결과뿐만 아니라, <strong>과정</strong>까지 투명하게 보여준다는 점에서 Headless Mode와 큰 차이입니다.</p><hr><h2 id="주요-ide-연동-예시" tabindex="-1">주요 IDE 연동 예시 <a class="header-anchor" href="#주요-ide-연동-예시" aria-label="Permalink to &quot;주요 IDE 연동 예시&quot;">​</a></h2><h3 id="zed" tabindex="-1">Zed <a class="header-anchor" href="#zed" aria-label="Permalink to &quot;Zed&quot;">​</a></h3><p>Zed는 ACP를 공식 지원하는 에디터 중 하나입니다.</p><ul><li>Zed 설정에서 Grok Agent를 추가</li><li><code>grok agent stdio</code>를 백엔드로 지정</li><li>Zed 내에서 Grok과 실시간으로 협업 가능</li></ul><h3 id="neovim" tabindex="-1">Neovim <a class="header-anchor" href="#neovim" aria-label="Permalink to &quot;Neovim&quot;">​</a></h3><p>Neovim 사용자들은 ACP 플러그인을 통해 Grok을 연동할 수 있습니다.</p><ul><li><code>grok agent stdio</code> 실행</li><li>Neovim 플러그인이 ACP 클라이언트 역할 수행</li><li>코드 작성, 리뷰, 리팩터링 등을 Vim 안에서 직접 요청 가능</li></ul><h3 id="emacs" tabindex="-1">Emacs <a class="header-anchor" href="#emacs" aria-label="Permalink to &quot;Emacs&quot;">​</a></h3><p>Emacs에도 ACP 지원 패키지가 있으며, <code>grok agent stdio</code>를 백엔드로 연결해서 사용합니다.</p><h3 id="커스텀-도구" tabindex="-1">커스텀 도구 <a class="header-anchor" href="#커스텀-도구" aria-label="Permalink to &quot;커스텀 도구&quot;">​</a></h3><p>자신만의 IDE나 내부 도구를 만들고 있다면, ACP 클라이언트 라이브러리를 사용해서 직접 <code>grok agent stdio</code>와 통신하는 프로그램을 만들 수 있습니다.</p><hr><h2 id="agent-mode-시작하기" tabindex="-1">Agent Mode 시작하기 <a class="header-anchor" href="#agent-mode-시작하기" aria-label="Permalink to &quot;Agent Mode 시작하기&quot;">​</a></h2><h3 id="_1-기본-실행" tabindex="-1">1. 기본 실행 <a class="header-anchor" href="#_1-기본-실행" aria-label="Permalink to &quot;1. 기본 실행&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">grok</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agent</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stdio</span></span></code></pre></div><h3 id="_2-특정-모델로-실행" tabindex="-1">2. 특정 모델로 실행 <a class="header-anchor" href="#_2-특정-모델로-실행" aria-label="Permalink to &quot;2. 특정 모델로 실행&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">grok</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agent</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stdio</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> grok-build</span></span></code></pre></div><h3 id="_3-yolo-모드로-실행-자동-승인" tabindex="-1">3. YOLO 모드로 실행 (자동 승인) <a class="header-anchor" href="#_3-yolo-모드로-실행-자동-승인" aria-label="Permalink to &quot;3. YOLO 모드로 실행 (자동 승인)&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">grok</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agent</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stdio</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --yolo</span></span></code></pre></div><h3 id="_4-ide에서-연결" tabindex="-1">4. IDE에서 연결 <a class="header-anchor" href="#_4-ide에서-연결" aria-label="Permalink to &quot;4. IDE에서 연결&quot;">​</a></h3><p>각 IDE(또는 ACP 클라이언트)에서 <code>grok agent stdio</code>를 백엔드 프로세스로 지정하면 됩니다.</p><p>(자세한 설정 방법은 각 IDE의 ACP 플러그인 문서를 참고하세요.)</p><hr><p>지금까지 Agent Mode의 실제 동작 흐름, 권한 관리, 사고 과정 관찰, IDE 연동 예시, 그리고 시작 방법을 다루었습니다.</p><hr><h2 id="agent-mode-전체-옵션-정리" tabindex="-1">Agent Mode 전체 옵션 정리 <a class="header-anchor" href="#agent-mode-전체-옵션-정리" aria-label="Permalink to &quot;Agent Mode 전체 옵션 정리&quot;">​</a></h2><p>Agent Mode에서 사용할 수 있는 주요 옵션들을 정리했습니다.</p><h3 id="기본-옵션" tabindex="-1">기본 옵션 <a class="header-anchor" href="#기본-옵션" aria-label="Permalink to &quot;기본 옵션&quot;">​</a></h3><ul><li><code>-m, --model &lt;MODEL&gt;</code>: 사용할 모델 지정 (예: <code>grok-build</code>)</li><li><code>--yolo</code>: 모든 도구 실행을 자동으로 승인 (주의 필요)</li><li><code>--reauth</code>: 강제로 재인증 진행</li></ul><h3 id="stdio-모드-전용" tabindex="-1">stdio 모드 전용 <a class="header-anchor" href="#stdio-모드-전용" aria-label="Permalink to &quot;stdio 모드 전용&quot;">​</a></h3><ul><li><code>grok agent stdio</code>: JSON-RPC를 stdin/stdout으로 통신</li></ul><h3 id="server-mode-http-1" tabindex="-1">Server Mode (HTTP) <a class="header-anchor" href="#server-mode-http-1" aria-label="Permalink to &quot;Server Mode (HTTP)&quot;">​</a></h3><ul><li><code>grok agent serve --bind &lt;IP:PORT&gt; --secret &lt;TOKEN&gt;</code>: HTTP 서버로 실행</li></ul><p>Agent Mode는 TUI와 달리 <strong>지속적으로 실행</strong>되는 서버 형태이기 때문에, 옵션이 상대적으로 간단합니다.</p><hr><h2 id="고급-설정" tabindex="-1">고급 설정 <a class="header-anchor" href="#고급-설정" aria-label="Permalink to &quot;고급 설정&quot;">​</a></h2><h3 id="모델-지정" tabindex="-1">모델 지정 <a class="header-anchor" href="#모델-지정" aria-label="Permalink to &quot;모델 지정&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">grok</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agent</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stdio</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> grok-4</span></span></code></pre></div><p>특정 작업에 더 적합한 모델을 사용하고 싶을 때 유용합니다.</p><h3 id="yolo-모드-1" tabindex="-1">YOLO 모드 <a class="header-anchor" href="#yolo-모드-1" aria-label="Permalink to &quot;YOLO 모드&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">grok</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agent</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stdio</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --yolo</span></span></code></pre></div><p>모든 도구 실행을 자동으로 승인합니다.<br> CI/CD나 자동화 환경에서는 편리하지만, <strong>보안상 중요한 환경에서는 사용을 자제</strong>하는 것이 좋습니다.</p><h3 id="강제-재인증" tabindex="-1">강제 재인증 <a class="header-anchor" href="#강제-재인증" aria-label="Permalink to &quot;강제 재인증&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">grok</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agent</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stdio</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --reauth</span></span></code></pre></div><p>인증 토큰이 만료되거나, 다른 계정으로 전환하고 싶을 때 사용합니다.</p><hr><h2 id="agent-mode-vs-headless-mode-vs-tui-비교" tabindex="-1">Agent Mode vs Headless Mode vs TUI 비교 <a class="header-anchor" href="#agent-mode-vs-headless-mode-vs-tui-비교" aria-label="Permalink to &quot;Agent Mode vs Headless Mode vs TUI 비교&quot;">​</a></h2><table tabindex="0"><thead><tr><th>구분</th><th>TUI (기본)</th><th>Headless Mode</th><th>Agent Mode (ACP)</th></tr></thead><tbody><tr><td>실행 형태</td><td>인터랙티브 전체 화면</td><td>한 번 실행 → 결과 받고 종료</td><td>지속 실행 (서버)</td></tr><tr><td>사용자 인터페이스</td><td>터미널 UI</td><td>없음 (텍스트/JSON 출력)</td><td>IDE/에디터 UI</td></tr><tr><td>세션 관리</td><td>강력</td><td>제한적</td><td>매우 강력 (ACP 세션)</td></tr><tr><td>도구 확인</td><td>TUI에서 실시간 확인</td><td>결과에 포함</td><td>실시간 Thought Stream + Tool Call</td></tr><tr><td>권한 처리</td><td>TUI에서 실시간 승인</td><td>YOLO 또는 사전 설정</td><td>실시간 권한 요청 (IDE)</td></tr><tr><td>주요 용도</td><td>일상 개발</td><td>스크립트, CI/CD</td><td>IDE 연동, 실시간 협업</td></tr><tr><td>통신 방식</td><td>-</td><td>stdout</td><td>JSON-RPC (ACP)</td></tr></tbody></table><p><strong>한 줄 요약</strong>:</p><ul><li><strong>TUI</strong>: 사람이 직접 대화하며 사용</li><li><strong>Headless</strong>: 프로그램이 Grok에게 일을 시키고 결과 받음</li><li><strong>Agent Mode</strong>: IDE/에디터 안에 Grok을 &quot;살아있는 AI&quot;로 넣음</li></ul><hr><h2 id="agent-mode-사용-시-주의할-점과-best-practices" tabindex="-1">Agent Mode 사용 시 주의할 점과 Best Practices <a class="header-anchor" href="#agent-mode-사용-시-주의할-점과-best-practices" aria-label="Permalink to &quot;Agent Mode 사용 시 주의할 점과 Best Practices&quot;">​</a></h2><h3 id="_1-yolo-모드는-신중하게" tabindex="-1">1. YOLO 모드는 신중하게 <a class="header-anchor" href="#_1-yolo-모드는-신중하게" aria-label="Permalink to &quot;1. YOLO 모드는 신중하게&quot;">​</a></h3><p><code>--yolo</code>를 사용하면 IDE에서 매번 권한을 묻지 않습니다.<br> 편리하지만, 중요한 프로젝트에서는 <strong>의도치 않은 파일 수정</strong>이 발생할 수 있으니 주의하세요.</p><h3 id="_2-인증-상태-관리" tabindex="-1">2. 인증 상태 관리 <a class="header-anchor" href="#_2-인증-상태-관리" aria-label="Permalink to &quot;2. 인증 상태 관리&quot;">​</a></h3><p>Agent Mode는 장시간 실행되는 경우가 많습니다.<br> 인증 토큰이 만료되면 <code>--reauth</code> 옵션으로 재인증해야 합니다.</p><h3 id="_3-ide-확장-프로그램-신뢰" tabindex="-1">3. IDE 확장 프로그램 신뢰 <a class="header-anchor" href="#_3-ide-확장-프로그램-신뢰" aria-label="Permalink to &quot;3. IDE 확장 프로그램 신뢰&quot;">​</a></h3><p>Agent Mode는 IDE 확장 프로그램이 <code>grok agent stdio</code>를 실행하는 구조입니다.<br> 신뢰할 수 있는 공식 확장 프로그램만 사용하세요.</p><h3 id="_4-디버깅-방법" tabindex="-1">4. 디버깅 방법 <a class="header-anchor" href="#_4-디버깅-방법" aria-label="Permalink to &quot;4. 디버깅 방법&quot;">​</a></h3><p>Agent Mode가 제대로 동작하지 않을 때는:</p><ul><li><code>grok agent stdio</code>를 직접 터미널에서 실행해보기 (로그 확인)</li><li>IDE 로그에서 ACP 관련 에러 메시지 확인</li><li><code>/inspect</code> 명령어로 로드된 상태 확인 (TUI에서)</li></ul><h3 id="_5-best-practices" tabindex="-1">5. Best Practices <a class="header-anchor" href="#_5-best-practices" aria-label="Permalink to &quot;5. Best Practices&quot;">​</a></h3><ul><li>Agent Mode는 <strong>실시간 협업</strong>에 최적화되어 있음</li><li>장시간 실행 시 인증 상태를 주기적으로 확인</li><li>중요한 작업은 YOLO 모드 대신 권한 확인을 유지</li><li>IDE 확장 프로그램은 공식/검증된 것만 사용</li></ul><hr><h2 id="전체-가이드-마무리" tabindex="-1">전체 가이드 마무리 <a class="header-anchor" href="#전체-가이드-마무리" aria-label="Permalink to &quot;전체 가이드 마무리&quot;">​</a></h2><p><code>14-에이전트-모드.md</code>를 모두 읽었다면, 이제 Grok Build를 <strong>IDE와 깊게 연동</strong>하는 방법을 배운 것입니다.</p><h3 id="핵심-요약" tabindex="-1">핵심 요약 <a class="header-anchor" href="#핵심-요약" aria-label="Permalink to &quot;핵심 요약&quot;">​</a></h3><ul><li><strong>Agent Mode</strong>는 ACP(Agent Client Protocol)를 통해 IDE와 실시간으로 통신합니다.</li><li><code>grok agent stdio</code>가 가장 기본적인 실행 방식입니다.</li><li>Thought Stream, Tool Call, Permission Handling 등을 실시간으로 관찰/제어할 수 있습니다.</li><li>Zed, Neovim, Emacs 등 다양한 에디터에서 활용 가능합니다.</li></ul><h3 id="언제-agent-mode를-사용하면-좋을까" tabindex="-1">언제 Agent Mode를 사용하면 좋을까? <a class="header-anchor" href="#언제-agent-mode를-사용하면-좋을까" aria-label="Permalink to &quot;언제 Agent Mode를 사용하면 좋을까?&quot;">​</a></h3><ul><li>IDE 안에서 Grok과 <strong>실시간으로 함께 코딩</strong>하고 싶을 때</li><li>코드 작성, 리뷰, 리팩터링 등을 IDE 안에서 직접 요청하고 싶을 때</li><li>Thought Process(사고 과정)를 투명하게 보고 싶을 때</li><li>Headless 모드보다 더 강력한 세션 관리와 권한 제어가 필요할 때</li></ul><hr><p><strong>14-에이전트-모드.md 끝</strong></p><p>여기까지 Grok Build의 Agent Mode를 실전 관점에서 정리했습니다.</p><p>Agent Mode는 Grok Build를 단순한 터미널 도구에서 <strong>현대적인 AI-native 개발 환경</strong>의 핵심으로 만들어주는 중요한 기능입니다.</p><p>이제 Grok Build의 주요 실행 모드(TUI, Headless, Agent Mode)와 확장 기능(Skills, MCP, Plugins, Hooks, Memory, Project Rules)을 모두 살펴보았습니다.</p><p>필요한 부분부터 하나씩 도입하면서, 자신만의 개발 환경을 만들어가시길 응원합니다.</p><p>이 문서에서 다루지 않은 더 고급 활용법이나 특정 IDE에서의 연동 방법이 필요하시면 언제든 말씀해주세요.</p><hr><p><em>이 가이드는 ACP를 통한 IDE 연동 경험을 바탕으로 작성되었습니다.</em></p><hr><h2 id="배경-지식-이-기능이-왜-이렇게-동작하는가" tabindex="-1">배경 지식: 이 기능이 왜 이렇게 동작하는가 <a class="header-anchor" href="#배경-지식-이-기능이-왜-이렇게-동작하는가" aria-label="Permalink to &quot;배경 지식: 이 기능이 왜 이렇게 동작하는가&quot;">​</a></h2><blockquote><p><strong>참고</strong>: 이 섹션은 Grok 공식 문서에 명시된 설계 의도를 그대로 설명한 것이 아닙니다.<br> 실제 동작 방식과 관찰, 그리고 논리적 해석을 바탕으로 작성한 <strong>참고용 설명</strong>입니다.<br> xAI에서 공식적으로 발표한 설계 철학이 아니라는 점을 참고해 주세요.</p></blockquote><p>Agent Mode(ACP)가 현재와 같은 형태로 제공되는 배경과 특징을 정리했습니다.</p><h3 id="_1-왜-acp라는-별도의-프로토콜을-만들었나" tabindex="-1">1. 왜 ACP라는 별도의 프로토콜을 만들었나? <a class="header-anchor" href="#_1-왜-acp라는-별도의-프로토콜을-만들었나" aria-label="Permalink to &quot;1. 왜 ACP라는 별도의 프로토콜을 만들었나?&quot;">​</a></h3><p>IDE나 에디터 안에서 Grok을 사용하려면, 단순한 텍스트 입출력만으로는 부족합니다.<br> 실시간으로:</p><ul><li>어떤 도구를 사용하고 있는지 보여줘야 하고 (Tool visibility)</li><li>Grok의 사고 과정을 관찰할 수 있어야 하며 (Thought streams)</li><li>도구 실행 권한을 실시간으로 승인/거부할 수 있어야 합니다 (Interactive permission handling)</li></ul><p>이러한 요구사항을 체계적으로 지원하기 위해 **Agent Client Protocol (ACP)**이라는 표준을 만들었습니다.</p><h3 id="_2-왜-stdio가-기본이고-server-mode-http-도-지원하나" tabindex="-1">2. 왜 stdio가 기본이고, Server Mode(HTTP)도 지원하나? <a class="header-anchor" href="#_2-왜-stdio가-기본이고-server-mode-http-도-지원하나" aria-label="Permalink to &quot;2. 왜 stdio가 기본이고, Server Mode(HTTP)도 지원하나?&quot;">​</a></h3><ul><li><strong>stdio</strong>: 가장 간단하고, 별도의 네트워크 설정 없이 바로 사용할 수 있습니다. 대부분의 IDE 연동이 이 방식을 사용합니다.</li><li><strong>Server Mode (HTTP)</strong>: 여러 클라이언트가 동시에 접속하거나, 원격으로 Grok을 제어하고 싶을 때 유용합니다. (예: 팀 내부 공유 AI 에이전트)</li></ul><h3 id="_3-왜-thought-stream과-tool-call을-실시간으로-노출하나" tabindex="-1">3. 왜 Thought Stream과 Tool Call을 실시간으로 노출하나? <a class="header-anchor" href="#_3-왜-thought-stream과-tool-call을-실시간으로-노출하나" aria-label="Permalink to &quot;3. 왜 Thought Stream과 Tool Call을 실시간으로 노출하나?&quot;">​</a></h3><p>Headless 모드에서는 결과만 받지만, Agent Mode에서는 <strong>과정</strong>까지 볼 수 있게 했습니다.<br> 이를 통해 개발자는 &quot;Grok이 지금 무슨 생각을 하고 있는지&quot;, &quot;어떤 파일을 읽고 있는지&quot;를 실시간으로 파악할 수 있어, 신뢰 형성과 디버깅에 도움이 됩니다.</p><hr><h2 id="디버깅-체크리스트" tabindex="-1">디버깅 체크리스트 <a class="header-anchor" href="#디버깅-체크리스트" aria-label="Permalink to &quot;디버깅 체크리스트&quot;">​</a></h2><p>Agent Mode가 제대로 동작하지 않을 때, 아래 순서대로 확인해보세요.</p><h3 id="agent가-연결되지-않을-때" tabindex="-1">Agent가 연결되지 않을 때 <a class="header-anchor" href="#agent가-연결되지-않을-때" aria-label="Permalink to &quot;Agent가 연결되지 않을 때&quot;">​</a></h3><ol><li><strong>grok agent stdio</strong>가 정상적으로 실행되는지 터미널에서 직접 테스트</li><li>IDE의 ACP 플러그인 로그 확인 (Zed, Neovim 등)</li><li><code>grok agent stdio --reauth</code>로 인증 문제 해결 시도</li></ol><h3 id="권한-요청이-ide에-안-보일-때" tabindex="-1">권한 요청이 IDE에 안 보일 때 <a class="header-anchor" href="#권한-요청이-ide에-안-보일-때" aria-label="Permalink to &quot;권한 요청이 IDE에 안 보일 때&quot;">​</a></h3><ul><li>Agent Mode에서는 권한 요청이 <strong>IDE 쪽</strong>으로 전달되어야 합니다.</li><li>IDE 설정에서 &quot;Grok Agent&quot; 또는 &quot;ACP&quot; 관련 권한 설정이 올바른지 확인하세요.</li><li><code>--yolo</code>를 사용하면 권한 요청 자체가 발생하지 않습니다.</li></ul><h3 id="tool이-보이지-않거나-호출되지-않을-때" tabindex="-1">Tool이 보이지 않거나 호출되지 않을 때 <a class="header-anchor" href="#tool이-보이지-않거나-호출되지-않을-때" aria-label="Permalink to &quot;Tool이 보이지 않거나 호출되지 않을 때&quot;">​</a></h3><ul><li>Agent Mode에서는 도구 목록이 IDE에 실시간으로 전달됩니다.</li><li><code>/inspect</code> (TUI)나 IDE의 도구 패널에서 어떤 도구가 사용 가능한지 확인하세요.</li></ul><h3 id="thought-stream이-안-보일-때" tabindex="-1">Thought Stream이 안 보일 때 <a class="header-anchor" href="#thought-stream이-안-보일-때" aria-label="Permalink to &quot;Thought Stream이 안 보일 때&quot;">​</a></h3><ul><li>일부 IDE 플러그인은 Thought Stream을 아직 지원하지 않을 수 있습니다.</li><li>Zed나 최신 ACP 플러그인을 사용하는지 확인하세요.</li></ul><h3 id="연결이-자주-끊기거나-불안정할-때" tabindex="-1">연결이 자주 끊기거나 불안정할 때 <a class="header-anchor" href="#연결이-자주-끊기거나-불안정할-때" aria-label="Permalink to &quot;연결이 자주 끊기거나 불안정할 때&quot;">​</a></h3><ul><li><code>--reauth</code>로 인증 토큰을 갱신해보세요.</li><li>Agent Mode는 장시간 실행되는 경우가 많으니, 인증 상태를 주기적으로 확인하는 것이 좋습니다.</li></ul><hr><p>이 두 섹션은 Agent Mode를 사용할 때 발생하는 문제를 스스로 해결할 수 있도록 돕기 위해 추가되었습니다.</p>',172)])])}const k=e(s,[["render",l]]);export{g as __pageData,k as default};
